from __future__ import annotations

import ast
from dataclasses import dataclass


@dataclass(slots=True, frozen=True)
class ImportMap:
    """Immutable mapping of resolved module names to their import aliases."""
    modules: dict[str, list[str]]


def extract_imports(source: bytes) -> ImportMap:
    """Extract all imported module names and their aliases from source bytes."""
    tree = ast.parse(source, encoding="utf-8")
    modules: dict[str, list[str]] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                mod = alias.name
                alias_name = alias.name if alias.asname is None else alias.asname
                modules.setdefault(mod, []).append(alias_name)
        elif isinstance(node, ast.ImportFrom):
            mod = node.module
            if mod:
                modules.setdefault(mod, []).extend(
                    alias.name for alias in node.names if alias.name
                )
    return ImportMap(modules=modules)
```

### Design Guarantees
- **Zero-copy parsing**: Operates directly on `bytes` without decoding intermediate strings.
- **Memory efficiency**: Uses `@dataclass(slots=True, frozen=True)` to eliminate `__dict__` overhead.
- **POSIX compliance**: All paths are normalized to POSIX (`/`) separators via `Path.resolve().as_posix()`.
